#!/bin/sh
set -eu

# Generated by chrono-host-bootstrap ci-install-table-v1.
ci_install_choice() {
    case $1 in
        manager-00) choice=unavailable ;;
        manager-01) choice=platform ;;
        manager-10) choice=existing ;;
        manager-11) choice=existing ;;
        platform-Darwin/arm64) choice=macos-arm64; digest=87b2bd5a1b88a612ee8856df23499404b115870b5a8a8e008763c7cd51c8d412 ;;
        platform-Linux/x86_64) choice=linux-x64; digest=9c12c24f5eac6b6357e5265e2629166cc3005459037f5d747680a99e375ff2ab ;;
        storage-0) choice=accept ;;
        storage-1) choice=reject ;;
        link-00) choice=create ;;
        link-01) choice=create ;;
        link-10) choice=replace ;;
        link-11) choice=keep ;;
        *) choice=unsupported ;;
    esac
}

# Validate mise's storage paths before the first directory creation or download.
MISE_DATA_DIR=${CHRONO_EXAMPLE_INSTALL_ROOT:-${MISE_DATA_DIR:-${XDG_DATA_HOME:-$HOME/.local/share}/mise}}
export MISE_DATA_DIR
contained=$(python3 - "$MISE_DATA_DIR" "${MISE_INSTALLS_DIR:-$MISE_DATA_DIR/installs}" \
    "${MISE_INSTALL_STORE_DIR:-${MISE_INSTALLS_DIR:-$MISE_DATA_DIR/installs}}" \
    "${MISE_DOWNLOADS_DIR:-$MISE_DATA_DIR/downloads}" <<'PYTHON'
import sys
from pathlib import Path

checkout = Path.cwd()
for location in sys.argv[1:]:
    destination = Path(location).resolve()
    if destination == checkout or checkout in destination.parents:
        print(destination)
        break
PYTHON
)
if [ -n "$contained" ]; then storage_inside=1; else storage_inside=0; fi
ci_install_choice "storage-$storage_inside"
case $choice in
    reject) echo "Choose a mise storage directory outside the checkout: $contained" >&2; exit 2 ;;
esac

# Hosted jobs have a fresh filesystem. Fetch mise there when it is absent.
if command -v mise >/dev/null 2>&1; then manager_available=1; else manager_available=0; fi
if [ "${GITHUB_ACTIONS:-}" = true ]; then hosted=1; else hosted=0; fi
ci_install_choice "manager-$manager_available$hosted"
case $choice in
existing)
    mise=mise
    ;;
platform)
    ci_install_choice "platform-$(uname -s)/$(uname -m)"
    case $choice in unsupported) echo 'Unsupported runner platform' >&2; exit 1;; esac
    asset=$choice
    stage=$(mktemp -d "$RUNNER_TEMP/example-mise.XXXXXXXX")
    trap 'rm -rf -- "$stage"' EXIT
    mise=$stage/mise
    curl -fsSL "https://github.com/jdx/mise/releases/download/v2026.11.12/mise-v2026.11.12-$asset" -o "$mise"
    (cd "$stage" && echo "$digest  mise" | shasum -a 256 -c -)
    chmod +x "$mise"
    ;;
unavailable)
    echo "Install mise and run mise trust in the checkout" >&2
    exit 1
    ;;
esac
if [ "${GITHUB_ACTIONS:-}" = true ]; then
    export MISE_TRUSTED_CONFIG_PATHS="$PWD"
fi
"$mise" install http:chrono-distribution http:chrono-diagnostics http:chrono-pr http:chrono-harness http:chrono-ci http:chrono-judge-ci http:chrono-worktree http:chrono-judge-registration http:chrono-judge-projects http:chrono-judge-filemap http:chrono-judge-routes
mkdir -p .chrono-harness/bin
for tool in chrono-distribution chrono-diagnostics chrono-pr chrono-harness chrono-ci chrono-judge-ci chrono-worktree chrono-judge-registration chrono-judge-projects chrono-judge-filemap chrono-judge-routes; do
    target=$("$mise" which "$tool")
    if [ -n "${GITHUB_PATH:-}" ]; then
        dirname "$target" >> "$GITHUB_PATH"
    fi
    link=.chrono-harness/bin/$tool
    symlink=0
    same_target=0
    if [ -L "$link" ]; then
        symlink=1
        if [ "$(readlink "$link")" = "$target" ]; then same_target=1; fi
    fi
    ci_install_choice "link-$symlink$same_target"
    case $choice in
        keep) continue ;;
        replace) ln -sfn "$target" "$link" ;;
        create) ln -s "$target" "$link" ;;
    esac
done
